def search_research_areas(name, page=None, items_per_page=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0136000" if __import__("os").path.isdir("./environment_mix/0136000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_str(s):
        s = s.strip()
        s = re.sub(r"\s+", " ", s)
        return s

    def _log(status_code, status, message=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "service": "paperswithcode",
            "endpoint": "search_research_areas",
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status,
            "status_code": status_code,
            "message": message,
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _check_limits():
        # If no quotas config exists, allow.
        quotas = _load("quotas.json")
        if not isinstance(quotas, list):
            return None
        if len(quotas) == 0:
            return None
        # Find a usable quota row for this service; pick first active matching.
        q = None
        for r in quotas:
            if isinstance(r, dict) and r.get("service") in (None, "paperswithcode") and r.get("status", "active") == "active":
                q = r
                break
        if not q:
            return None

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        # Rate limit: requests_per_minute
        rpm = q.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            recent = 0
            for lr in logs:
                if not isinstance(lr, dict):
                    continue
                if lr.get("service") != "paperswithcode":
                    continue
                ts = lr.get("timestamp")
                if isinstance(ts, str):
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= cutoff:
                        recent += 1
            if recent >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded.", limit=rpm, window_seconds=60)

        # Daily quota: requests_per_day
        rpd = q.get("requests_per_day")
        if isinstance(rpd, int) and rpd > 0:
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=1)
            recent = 0
            for lr in logs:
                if not isinstance(lr, dict):
                    continue
                if lr.get("service") != "paperswithcode":
                    continue
                ts = lr.get("timestamp")
                if isinstance(ts, str):
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= cutoff:
                        recent += 1
            if recent >= rpd:
                return _err("QUOTA_EXCEEDED", "Request quota exceeded.", limit=rpd, window_seconds=86400)

        return None

    # Auth is ambient; if there is an authz config and none allows access, return UNAUTHORIZED.
    # We interpret absence of auth config as allowed.
    authz = _load("authz.json")
    if isinstance(authz, list) and len(authz) > 0:
        allowed = any(isinstance(r, dict) and r.get("service") in (None, "paperswithcode") and r.get("status", "active") == "active" for r in authz)
        if not allowed:
            _log(401, "error", "Unauthorized")
            return _err("UNAUTHORIZED", "Caller is not permitted to use the service.")

    lim = _check_limits()
    if lim:
        _log(429, "error", lim["error"]["message"])
        return lim

    # Validate inputs
    if not isinstance(name, str):
        _log(400, "error", "Validation error: name must be a string")
        return _err("VALIDATION_ERROR", "name must be a string.")
    qname = _norm_str(name)
    if qname == "":
        _log(400, "error", "Validation error: name must not be empty")
        return _err("VALIDATION_ERROR", "name must not be empty.")

    if page is None:
        page = 1
    if items_per_page is None:
        items_per_page = 20

    if not isinstance(page, int) or page <= 0:
        _log(400, "error", "Validation error: page must be a positive integer")
        return _err("VALIDATION_ERROR", "page must be a positive integer.")
    if not isinstance(items_per_page, int) or items_per_page <= 0:
        _log(400, "error", "Validation error: items_per_page must be a positive integer")
        return _err("VALIDATION_ERROR", "items_per_page must be a positive integer.")

    items_per_page = min(items_per_page, 100)

    # Load and filter
    areas = _load("research_areas.json")
    if not isinstance(areas, list):
        areas = []

    qlow = qname.lower()
    matches = []
    for a in areas:
        if not isinstance(a, dict):
            continue
        st = a.get("status")
        if st not in ("active", "deprecated"):
            continue
        slug = a.get("slug")
        aname = a.get("name")
        if isinstance(slug, str) and slug.lower() == qlow:
            matches.append(a)
            continue
        if isinstance(aname, str) and qlow in aname.lower():
            matches.append(a)
            continue

    # Sort: stable, by name then id
    def _k(r):
        n = r.get("name")
        i = r.get("id")
        return ((n or "").lower(), i or "")
    matches.sort(key=_k)

    total = len(matches)
    start = (page - 1) * items_per_page
    end = start + items_per_page
    page_rows = matches[start:end] if start < total else []
    has_more = end < total
    next_cursor = page + 1 if has_more else None

    resp = {
        "data": page_rows,
        "meta": {
            "page": page,
            "items_per_page": items_per_page,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
    _log(200, "ok")
    return resp

