            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_conferences"

    def _log(status, credential_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            row = {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": datetime.datetime.utcnow().isoformat() + "Z",
            }
            if isinstance(meta, dict):
                row.update(meta)
            logs.append(row)
            _save("request_logs.json", logs)

    def _check_limits():
        logs = _load("request_logs.json")
        if not isinstance(logs, list) or len(logs) == 0:
            return None
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=60)
        c = 0
        for r in reversed(logs[-2000:]):
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                rt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if rt < cutoff:
                continue
            if r.get("endpoint") == endpoint:
                c += 1
        if c >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    lim = _check_limits()
    if lim:
        _log("error", error_code=lim["error"]["code"])
        return lim

    # --- Validation ---
    if conference_name is not None:
        if not isinstance(conference_name, str):
            e = _err("VALIDATION_ERROR", "conference_name must be a string or null.", field="conference_name")
            _log("error", error_code=e["error"]["code"])
            return e
        if conference_name.strip() == "":
            e = _err("VALIDATION_ERROR", "conference_name cannot be empty when provided.", field="conference_name")
            _log("error", error_code=e["error"]["code"])
            return e
        conference_name = conference_name.strip()

    if page is None:
        page = 1
    if items_per_page is None:
        items_per_page = 20
    if not isinstance(page, int) or page <= 0:
        e = _err("VALIDATION_ERROR", "page must be a positive integer.", field="page")
        _log("error", error_code=e["error"]["code"])
        return e
    if not isinstance(items_per_page, int) or items_per_page <= 0:
        e = _err("VALIDATION_ERROR", "items_per_page must be a positive integer.", field="items_per_page")
        _log("error", error_code=e["error"]["code"])
        return e
    items_per_page = max(1, min(int(items_per_page), 100))

    venues = _load("venues.json")
    if not isinstance(venues, list):
        e = _err("UNAUTHORIZED", "Service unavailable for this operation.")
        _log("error", error_code=e["error"]["code"])
        return e

    q = conference_name.lower() if isinstance(conference_name, str) else None
    matched = []
    for v in venues:
        if not isinstance(v, dict):
            continue
        if v.get("venue_type") != "conference":
            continue
        if v.get("status") == "deleted":
            continue
        if q is not None:
            name = v.get("name")
            if not isinstance(name, str) or q not in name.lower():
                continue
        matched.append(v)

    # Sort by name asc then id
    matched.sort(key=lambda x: ((x.get("name") or "").lower(), x.get("id") or ""))

    total = len(matched)
    start = (page - 1) * items_per_page
    end = start + items_per_page
    page_items = matched[start:end] if start < total else []
    has_more = end < total
    next_cursor = page + 1 if has_more else None

    _log("ok", meta={"result_count": len(page_items), "total": total})
    return {
        "conferences": page_items,
        "pagination": {
            "page": page,
            "items_per_page": items_per_page,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

