def search_papers(abstract=None, title=None, arxiv_id=None, page=None, items_per_page=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0136000" if __import__("os").path.isdir("./environment_mix/0136000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _endpoint = "search_papers"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _get_client_key():
        # Ambient authentication: identify caller deterministically from invocation context.
        seed = repr(sorted(_extra.items()))
        return hashlib.sha256(seed.encode("utf-8")).hexdigest()[:32] or "anonymous"

    def _log_and_return(payload, status="ok", code=None):
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": _endpoint,
            "client": _get_client_key(),
            "status": status,
            "error_code": code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)
        return payload

    def _enforce_limits():
        # Simple observable service dynamics using request_logs.json if present.
        # Rate limit: 120 requests per rolling 60 seconds per client.
        # Quota: 10,000 requests per rolling 30 days per client.
        client = _get_client_key()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.utcnow()
        win_rate = now - datetime.timedelta(seconds=60)
        win_quota = now - datetime.timedelta(days=30)

        def _parse_ts(s):
            if not isinstance(s, str):
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        recent_60 = 0
        recent_30d = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("client") != client:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if not ts:
                continue
            if ts >= win_rate:
                recent_60 += 1
            if ts >= win_quota:
                recent_30d += 1

        if recent_60 >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit="120/min", window_seconds=60)
        if recent_30d >= 10000:
            return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded.", limit="10000/30d", window_days=30)
        return None

    rl = _enforce_limits()
    if rl:
        return _log_and_return(rl, status="error", code=rl["error"]["code"])

    # Validate search fields
    def _is_blank(x):
        return x is None or (isinstance(x, str) and x.strip() == "")

    if _is_blank(title) and _is_blank(abstract) and _is_blank(arxiv_id):
        return _log_and_return(_err("VALIDATION_ERROR", "At least one of title, abstract, or arxiv_id must be provided."), status="error", code="VALIDATION_ERROR")

    for k, v in (("title", title), ("abstract", abstract), ("arxiv_id", arxiv_id)):
        if v is not None and not isinstance(v, str):
            return _log_and_return(_err("VALIDATION_ERROR", f"{k} must be a string or null."), status="error", code="VALIDATION_ERROR")

    if page is None:
        page = 1
    if items_per_page is None:
        items_per_page = 20
    if not isinstance(page, int) or not isinstance(items_per_page, int):
        return _log_and_return(_err("VALIDATION_ERROR", "page and items_per_page must be integers."), status="error", code="VALIDATION_ERROR")
    if page < 1 or items_per_page < 1:
        return _log_and_return(_err("VALIDATION_ERROR", "page and items_per_page must be >= 1 (1-based pagination)."), status="error", code="VALIDATION_ERROR")
    items_per_page = max(1, min(100, items_per_page))

    def _normalize_arxiv(a):
        if not isinstance(a, str):
            return None
        a = a.strip()
        if a == "":
            return None
        # Drop version suffix like v2
        m = re.match(r"^(\d{4}\.\d{4,5})(v\d+)?$", a)
        if m:
            return m.group(1)
        # Old style
        m = re.match(r"^([a-zA-Z\-]+\/\d{7})(v\d+)?$", a)
        if m:
            return m.group(1)
        # If provided is like url or has vN, strip vN at end if present
        a = re.sub(r"(v\d+)$", "", a)
        return a

    q_title = title.strip().lower() if isinstance(title, str) and title.strip() != "" else None
    q_abs = abstract.strip().lower() if isinstance(abstract, str) and abstract.strip() != "" else None
    q_arxiv = _normalize_arxiv(arxiv_id) if isinstance(arxiv_id, str) and arxiv_id.strip() != "" else None

    papers = _load("papers.json")
    if not isinstance(papers, list):
        papers = []

    matches = []
    for p in papers:
        if not isinstance(p, dict):
            continue
        if p.get("status") == "deleted":
            continue
        # arxiv exact normalized
        if q_arxiv:
            pa = _normalize_arxiv(p.get("arxiv_id")) if isinstance(p.get("arxiv_id"), str) else None
            if pa != q_arxiv:
                continue
        # title substring
        if q_title:
            pt = p.get("title") or ""
            if not isinstance(pt, str) or q_title not in pt.lower():
                continue
        # abstract substring
        if q_abs:
            pab = p.get("abstract") or ""
            if not isinstance(pab, str) or q_abs not in pab.lower():
                continue
        matches.append(p)

    # Sort: most recently updated first, then created_at, then id
    def _sort_key(p):
        ua = p.get("updated_at")
        ca = p.get("created_at")
        return (
            ua if isinstance(ua, str) else "",
            ca if isinstance(ca, str) else "",
            p.get("id") or "",
        )
    matches.sort(key=_sort_key, reverse=True)

    total = len(matches)
    start = (page - 1) * items_per_page
    end = start + items_per_page
    page_items = matches[start:end] if start < total else []
    has_more = end < total

    # Cursor: simple next-page cursor
    next_cursor = str(page + 1) if has_more else None

    resp = {
        "papers": page_items,
        "page": page,
        "items_per_page": items_per_page,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
    return _log_and_return(resp, status="ok")

