def list_paper_tasks(paper_id, page=None, items_per_page=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0136000" if __import__("os").path.isdir("./environment_mix/0136000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _endpoint = "list_paper_tasks"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts_any(row):
        if not isinstance(row, dict):
            return None
        ts = row.get("timestamp") or row.get("created_at")
        if isinstance(ts, str) and ts:
            try:
                return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                return None
        return None

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _enforce_limits():
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rl = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        logs = _load_logs()
        now = datetime.datetime.utcnow()

        if isinstance(rl, int) and rl > 0:
            cutoff = now - datetime.timedelta(seconds=60)
            c = 0
            for r in reversed(logs):
                dt = _parse_ts_any(r)
                if not dt:
                    continue
                if dt < cutoff:
                    break
                c += 1
                if c >= rl:
                    return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rl)

        if isinstance(quota, int) and quota > 0:
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for r in reversed(logs):
                dt = _parse_ts_any(r)
                if not dt:
                    continue
                if dt < cutoff:
                    break
                c += 1
                if c >= quota:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota_per_day=quota)

        return None

    def _log(status, error_code=None):
        logs = _load_logs()
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": _endpoint,
                "timestamp": _now_iso(),
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save("request_logs.json", logs)

    if not isinstance(paper_id, str) or not paper_id.strip():
        e = _err("VALIDATION_ERROR", "paper_id must be a non-empty string.", paper_id=paper_id)
        _log("error", e["error"]["code"])
        return e
    paper_id = paper_id.strip()

    if page is None:
        page = 1
    if items_per_page is None:
        items_per_page = 20
    if not isinstance(page, int) or page < 1:
        e = _err("VALIDATION_ERROR", "page must be a positive integer.", page=page)
        _log("error", e["error"]["code"])
        return e
    if not isinstance(items_per_page, int) or items_per_page < 1:
        e = _err("VALIDATION_ERROR", "items_per_page must be a positive integer.", items_per_page=items_per_page)
        _log("error", e["error"]["code"])
        return e
    if items_per_page > 100:
        items_per_page = 100

    lim = _enforce_limits()
    if lim:
        _log("error", lim["error"]["code"])
        return lim

    papers = _load("papers.json")
    if not isinstance(papers, list):
        papers = []

    paper = None
    for p in papers:
        if isinstance(p, dict) and p.get("id") == paper_id:
            paper = p
            break

    if not paper or paper.get("status") == "deleted":
        e = _err("NOT_FOUND", "Paper not found.", paper_id=paper_id)
        _log("error", e["error"]["code"])
        return e

    tasks = paper.get("tasks")
    if not isinstance(tasks, list):
        tasks = []

    total = len(tasks)
    start = (page - 1) * items_per_page
    end = start + items_per_page
    page_rows = tasks[start:end]
    has_more = end < total

    _log("ok")
    return {
        "tasks": page_rows,
        "page": page,
        "items_per_page": items_per_page,
        "total": total,
        "has_more": has_more,
        "next_page": (page + 1) if has_more else None,
        "paper_id": paper_id,
    }

def read_paper_from_url(paper_url, **_extra):
    import json, os, datetime, time, re, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0136000" if __import__("os").path.isdir("./environment_mix/0136000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _endpoint = "read_paper_from_url"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts_any(row):
        if not isinstance(row, dict):
            return None
        ts = row.get("timestamp") or row.get("created_at")
        if isinstance(ts, str) and ts:
            try:
                return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                return None
        return None

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _enforce_limits():
        cfg = _load("service_config.json")
        if not isinstance(cfg, dict):
            cfg = {}
        rl = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        logs = _load_logs()
        now = datetime.datetime.utcnow()

        if isinstance(rl, int) and rl > 0:
            cutoff = now - datetime.timedelta(seconds=60)
            c = 0
            for r in reversed(logs):
                dt = _parse_ts_any(r)
                if not dt:
                    continue
                if dt < cutoff:
                    break
                c += 1
                if c >= rl:
                    return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rl)

        if isinstance(quota, int) and quota > 0:
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for r in reversed(logs):
                dt = _parse_ts_any(r)
                if not dt:
                    continue
                if dt < cutoff:
                    break
                c += 1
                if c >= quota:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota_per_day=quota)

        return None

    def _log(status, error_code=None):
        logs = _load_logs()
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": _endpoint,
                "timestamp": _now_iso(),
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save("request_logs.json", logs)

    # Validate URL
    if not isinstance(paper_url, str) or not paper_url.strip():
        e = _err("VALIDATION_ERROR", "paper_url must be a non-empty string.", paper_url=paper_url)
        _log("error", e["error"]["code"])
        return e

    raw = paper_url.strip()
    try:
        parsed = urllib.parse.urlparse(raw)
    except Exception:
        e = _err("VALIDATION_ERROR", "paper_url is not a valid URL.", paper_url=paper_url)
        _log("error", e["error"]["code"])
        return e

    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        e = _err("VALIDATION_ERROR", "paper_url must be an absolute http(s) URL.", paper_url=paper_url)
        _log("error", e["error"]["code"])
        return e

    lim = _enforce_limits()
    if lim:
        _log("error", lim["error"]["code"])
        return lim

    def _normalize_url(u):
        p = urllib.parse.urlparse(u.strip())
        scheme = p.scheme.lower()
        netloc = p.netloc.lower()
        if netloc.endswith(":80") and scheme == "http":
            netloc = netloc[:-3]
        if netloc.endswith(":443") and scheme == "https":
            netloc = netloc[:-4]
        path = urllib.parse.unquote(p.path or "")
        path = re.sub(r"/+", "/", path).rstrip("/")
        if not path:
            path = "/"
        # drop query+fragment for canonical mapping (PWC typically treats them as non-semantic)
        return urllib.parse.urlunparse((scheme, netloc, path, "", "", ""))

    norm_url = _normalize_url(raw)

    papers = _load("papers.json")
    if not isinstance(papers, list):
        papers = []

    resolved = None
    resolved_reason = None

    # 1) exact match on paper_url (normalized compare)
    for p in papers:
        if not isinstance(p, dict) or p.get("status") == "deleted":
            continue
        pu = p.get("paper_url")
        if isinstance(pu, str) and pu.strip():
            if _normalize_url(pu) == norm_url:
                resolved = p
                resolved_reason = "paper_url"
                break

    # 2) match in url_aliases (normalized)
    if resolved is None:
        for p in papers:
            if not isinstance(p, dict) or p.get("status") == "deleted":
                continue
            aliases = p.get("url_aliases")
            if not isinstance(aliases, list):
                continue
            for a in aliases:
                if isinstance(a, str) and a.strip() and _normalize_url(a) == norm_url:
                    resolved = p
                    resolved_reason = "url_aliases"
                    break
            if resolved is not None:
                break

    # 3) detect arxiv id in URL and resolve by arxiv_id normalized (strip version)
    def _norm_arxiv(a):
        if not isinstance(a, str):
            return None
        a = a.strip()
        if not a:
            return None
        a = re.sub(r"^arxiv:", "", a, flags=re.I)
        a = a.split("v", 1)[0] if re.match(r"^\d{4}\.\d{4,5}v\d+$", a) else a.split("v", 1)[0] if re.match(r"^[a-z\-]+\/\d{7}v\d+$", a, flags=re.I) else a
        return a.lower()

    if resolved is None:
        m = re.search(r"(?:abs|pdf)/(\d{4}\.\d{4,5})(?:v\d+)?", norm_url)
        if not m:
            m = re.search(r"/(\d{4}\.\d{4,5})(?:v\d+)?(?:\.pdf)?$", norm_url)
        arx = m.group(1).lower() if m else None
        if arx:
            for p in papers:
                if not isinstance(p, dict) or p.get("status") == "deleted":
                    continue
                if _norm_arxiv(p.get("arxiv_id")) == arx:
                    resolved = p
                    resolved_reason = "arxiv_url"
                    break

    if resolved is None:
        e = _err("NOT_FOUND", "URL could not be mapped to a known paper.", paper_url=paper_url, normalized_url=norm_url)
        _log("error", e["error"]["code"])
        return e

    # Optionally populate/update cached_read (mirror behaviour)
    now_iso = _now_iso()
    changed = False
    cr = resolved.get("cached_read")
    if cr is None or not isinstance(cr, dict):
        cr = {
            "source_url": norm_url,
            "resolved_paper_id": resolved.get("id"),
            "extracted_text": None,
            "summary": None,
            "last_fetched_at": None,
            "fetch_status": "never_fetched",
            "error": None,
        }
        resolved["cached_read"] = cr
        changed = True

    # Update minimal cache metadata on read attempt (offline: mark fetched if we have extracted_text or summary already)
    cr["source_url"] = norm_url
    cr["resolved_paper_id"] = resolved.get("id")
    cr["last_fetched_at"] = now_iso
    if cr.get("extracted_text") or cr.get("summary"):
        cr["fetch_status"] = "fetched"
        cr["error"] = None
    else:
        # Keep "never_fetched" unless previously failed; but record we attempted
        if cr.get("fetch_status") not in ("failed", "fetched"):
            cr["fetch_status"] = "never_fetched"
    changed = True

    if changed:
        # persist updated cached_read into papers.json
        for i, p in enumerate(papers):
            if isinstance(p, dict) and p.get("id") == resolved.get("id"):
                papers[i] = resolved
                break
        _save("papers.json", papers)

    # Must have readable cached content to return; otherwise NOT_FOUND per rule
    if not (isinstance(resolved.get("cached_read"), dict) and (resolved["cached_read"].get("extracted_text") or resolved["cached_read"].get("summary"))):
        e = _err(
            "NOT_FOUND",
            "No readable cached content exists for this URL mapping.",
            paper_id=resolved.get("id"),
            resolution=resolved_reason,
        )
        _log("error", e["error"]["code"])
        return e

    _log("ok")
    return {
        "paper": resolved,
        "resolution": {"normalized_url": norm_url, "matched_via": resolved_reason, "paper_id": resolved.get("id")},
        "readout": resolved.get("cached_read"),
    }
